import * as E from './engine.mjs';
import {drawSpirit,drawPerson,drawTile,drawBuilding,renderSpiritCanvases} from './sprites.mjs';
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(name,label,value='',cls='btn')=>'<button class="'+cls+'" data-action="'+name+'" data-value="'+esc(value)+'">'+label+'</button>';
const chip=type=>'<span class="chip type-chip" style="--type:'+E.COLORS[type]+'">'+esc(type)+'</span>';
const sprite=(sp,form=0,size=128)=>'<canvas width="'+size+'" height="'+size+'" data-species="'+sp.id+'" data-form="'+form+'" role="img" aria-label="'+esc(sp.forms[form])+'"></canvas>';
let db,s,library={},view='explore',battle=null,selectedMove=0,style='normal',commit=.5,borrow=0,modal=null,toastTimer,saveTimer,keys=new Set(),lastStep=0,lastTime=performance.now(),ritual=null,queue=[],busy=false,aiStatus=null,starterChoices=[],starterBase='Beast',search='',filter='all',loaded=false;
const DB_NAME='spirimon-v1',COMPANION='http://127.0.0.1:4317';
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{req.result.createObjectStore('saves');req.result.createObjectStore('library',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbGet(store,key){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbAll(store){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbPut(store,value,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite'),os=tx.objectStore(store);key===undefined?os.put(value):os.put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function persist(){if(!loaded)return;try{s.lastSave=Date.now();s.battle=battle;s.generationQueue=queue;await dbPut('saves',structuredClone(s),'main');$('#save-status').innerHTML='<i></i> Saved on this device';}catch(err){$('#save-status').textContent='Save failed · export a backup';console.error(err);}}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,350);}
function register(sp){s.species[sp.id]=sp;library[sp.id]=sp;globalThis.spirimonSpecies=s.species;if(db)dbPut('library',structuredClone(sp)).catch(()=>toast('Species library is full. Export a backup.'));return sp;}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function note(msg){s.notes.unshift(msg);s.notes=s.notes.slice(0,100);save();}
function currentRegion(){const c=E.coord(s.player.x,s.player.y);return E.region(s.seed,c.cx,c.cy);}
function safe(){const c=E.coord(s.player.x,s.player.y);return currentRegion().town&&Math.abs(c.lx-24)<10&&Math.abs(c.ly-18)<8&&!battle;}
function party(){return s.party.map(id=>s.spirits.find(i=>i.id===id)).filter(Boolean);}
function lead(){return party().find(i=>i.hp>0);}
function spOf(i){return s.species[i.species];}
function abilityReady(kind){const types=party().filter(i=>i.hp>0).flatMap(i=>{const sp=spOf(i);return[sp.base,sp.alter,...sp.domains];});if(kind==='swim')return s.rank>=2&&types.some(t=>['Ooze','Elemental','Water'].includes(t));if(kind==='climb')return s.rank>=3&&types.some(t=>['Giant','Beast','Construct'].includes(t));return false;}
function speciesFor(reg,r){const base=E.pick(r()<.85?reg.biome.types:E.TYPES,r),alter=E.pick(E.TYPES.filter(t=>t!==base),r),pair=base+'>'+alter,known=(s.history[pair]||[]).map(id=>s.species[id]).filter(Boolean);if(known.length&&r()>=.1)return E.pick(known,r);const candidates=Object.values(library).filter(p=>p.base===base&&p.alter===alter&&!s.seen.includes(p.id));if(candidates.length)return register(E.pick(candidates,r));const sp=register(E.makeSpecies(E.hash(s.seed,reg.key,s.steps,r()),base,alter));if(s.settings.aiEnabled)queue.push(sp.id);return sp;}
function ensureRegion(cx,cy){const reg=E.region(s.seed,cx,cy);if(s.regions[reg.key])return reg;const r=E.rng(E.hash(s.seed,'ecosystem',cx,cy));s.regions[reg.key]={...reg,visited:false};const roam=[];for(let n=0;n<7;n++){const sp=speciesFor(reg,r);let x,y;for(let k=0;k<100;k++){x=cx*48+4+Math.floor(r()*40);y=cy*36+4+Math.floor(r()*28);const c=E.coord(x,y);if(E.walkable(E.tile(s.seed,x,y))&&(!reg.town||Math.abs(c.lx-24)>10||Math.abs(c.ly-18)>8))break;}const form=E.rollForm(r),level=Math.max(2,reg.danger+Math.floor(r()*4)+form*10);const ind=E.heal(E.makeIndividual(sp,level,form,r),sp);roam.push({id:'r-'+reg.key+'-'+n,x,y,ind,active:true});}if(cx===0&&cy===0&&roam.length){roam[0].x=34;roam[0].y=18;}s.roamers[reg.key]=roam;return reg;}
function discoverRegion(){const c=E.coord(s.player.x,s.player.y);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)ensureRegion(c.cx+dx,c.cy+dy);const reg=s.regions[c.cx+','+c.cy];if(!reg.visited){reg.visited=true;note('Discovered '+reg.name+' in '+reg.biome.name+'.');toast(reg.name+' · '+reg.biome.name);}save();}
function discover(sp){if(!s.seen.includes(sp.id)){s.seen.push(sp.id);const pair=sp.base+'>'+sp.alter;s.history[pair]??=[];if(!s.history[pair].includes(sp.id))s.history[pair].push(sp.id);note('Encountered '+sp.forms[0]+' ('+sp.base+' → '+sp.alter+').');}}
function nearbyNPC(){const c=E.coord(s.player.x,s.player.y);return E.npcs(s.seed,c.cx,c.cy).find(n=>Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2);}
function nearbyRoamer(){const c=E.coord(s.player.x,s.player.y);return(s.roamers[c.cx+','+c.cy]||[]).find(n=>n.active&&Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2);}
function removeRoamer(id){for(const group of Object.values(s.roamers)){const r=group.find(x=>x.id===id);if(r)r.active=false;}}
function hint(){if(!s.starter)return'Your first bond awaits at the guild';const n=nearbyNPC();if(n)return'E · Talk to '+n.name;const r=nearbyRoamer();if(r)return'E · Approach '+spOf(r.ind).forms[r.ind.appearance];if(s.drops.some(d=>d.x===s.player.x&&d.y===s.player.y))return'E · Retrieve your dropped supplies';return safe()?'A safe place · Rest, train, and attune':'The wild is calling · Follow a trail';}
function hpHTML(ind,sp){const max=E.stats(ind,sp).hp,pct=Math.max(0,ind.hp/max*100);return'<div class="health '+(pct<25?'critical':pct<50?'low':'')+'"><i style="width:'+pct+'%"></i></div><div class="health-label"><span>'+(ind.status?esc(ind.status.toUpperCase()):'HP')+'</span><span>'+ind.hp+' / '+max+'</span></div><div class="pp-meter"><i style="width:'+Math.min(100,(ind.pp??E.stats(ind,sp).pp)/E.stats(ind,sp).pp*100)+'%"></i></div><div class="health-label"><span>SHARED PP</span><span>'+(ind.pp??E.stats(ind,sp).pp)+' / '+E.stats(ind,sp).pp+'</span></div>';}
function partyHTML(){const members=party();return'<section class="panel party-panel"><div class="section-label">ATTUNED SPIRITS <small>'+members.length+' / 6</small></div><div class="party-list">'+members.map((i,n)=>{const sp=spOf(i);return'<button class="party-item" data-action="detail" data-value="'+i.id+'">'+sprite(sp,i.appearance,80)+'<div class="party-info"><div class="party-name"><span>'+esc(sp.forms[i.appearance])+'</span><small>Lv. '+i.level+'</small></div><div class="party-types">'+esc(sp.base)+' / '+esc(sp.alter)+(n===0?' · LEAD':'')+'</div>'+hpHTML(i,sp)+'</div></button>';}).join('')+Array.from({length:6-members.length},()=>'<div class="empty-slot"><span>◇</span> An unspoken bond</div>').join('')+'</div>'+action('view','Manage tattoos →','spirits','btn ghost party-manage')+'</section>';}
function exploreHTML(){const reg=currentRegion(),visited=Object.values(s.regions).filter(r=>r.visited).length;return'<div class="page-heading"><div><div class="eyebrow">YOUR JOURNEY, UNWRITTEN</div><h1>The wild is calling.</h1><p>Follow a trail. Find a spirit. Make a bond.</p></div><span class="pill gold">◇ &nbsp; Rank '+s.rank+' · '+rankName()+'</span></div><div class="explore-layout"><div><div class="world-frame"><canvas id="world" width="960" height="640" tabindex="0" aria-label="Explorable procedural world. Use arrow keys or WASD to move, E to interact."></canvas><div class="map-location"><small id="map-biome">'+esc(reg.biome.name.toUpperCase())+'</small><strong id="map-location">'+esc(reg.name)+'</strong></div><div class="map-compass"><small>N</small><b>✧</b></div><div class="dpad">'+['up','left','right','down'].map((d,i)=>action('step',['↑','←','→','↓'][i],d,'')).join('')+'</div><div class="map-hint" id="map-hint">'+esc(hint())+'</div><div class="map-coords" id="map-coords"></div></div><div class="world-toolbar"><div class="controls"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> move <span>·</span><kbd>E</kbd> interact <span>·</span><kbd>B</kbd> bag</div><div>'+action('interact','Interact &nbsp; ↵','','btn small')+' '+action('bag','Bag','','btn ghost small')+'</div></div><div class="stat-strip"><div class="stat-block"><span class="stat-icon">♧</span><div><strong>'+s.seen.length+'</strong><small>Spirits discovered</small></div></div><div class="stat-block"><span class="stat-icon">◇</span><div><strong>'+s.spirits.length+'</strong><small>Bonds sealed</small></div></div><div class="stat-block"><span class="stat-icon">⌖</span><div><strong>'+visited+'</strong><small>Regions explored</small></div></div><div class="stat-block"><span class="stat-icon">◉</span><div><strong>'+s.inventory.coins+'</strong><small>Guild marks</small></div></div></div></div><aside class="right-column">'+partyHTML()+'<section class="field-note"><div class="eyebrow">A SEALER’S FIELD NOTE</div><h3>Not every bond begins in battle.</h3><p>Approach a roaming spirit with an offering. A little patience can turn a wary encounter into a willing companion.</p></section><section class="panel quest-preview"><div class="section-label">ON YOUR PATH <small>OPTIONAL</small></div><h3>'+(s.quests.discovery?'Beyond the familiar':'First impressions')+'</h3><p>'+(s.quests.discovery?'Visit three regions, then speak to Scholar Elin.':'Discover five spirit species, then visit Scholar Elin.')+'</p><div class="progress-line"><i style="width:'+Math.min(100,(s.quests.discovery?visited/3:s.seen.length/5)*100)+'%"></i></div></section></aside></div>';}
function rankName(){return['','Initiate','Wayfarer','Binder','Warden','Spiritkeeper','Elder'][Math.min(6,s.rank)];}
function render(){if(!loaded)return;globalThis.spirimonSpecies=s.species;$('#main').innerHTML=view==='explore'?(battle?battleHTML():exploreHTML()):view==='spirits'?collectionHTML():view==='atlas'?atlasHTML():journalHTML();document.querySelectorAll('.nav-button[data-action="view"]').forEach(b=>b.classList.toggle('active',b.dataset.value===view));$('#footer-seed').textContent='WORLD '+s.seed+' · LOCAL FIRST';$('.player-avatar').textContent=s.player.name.slice(0,1).toUpperCase();applyLayout();renderSpiritCanvases();if(battle&&view==='explore')drawBattle();}
function showModal(title,body,options={}){keys.clear();modal=options.kind||'generic';document.body.classList.add('modal-open');$('#modal-root').innerHTML='<div class="modal-overlay"><section class="modal '+(options.wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'">'+(options.lock?'':action('close','×','','modal-close'))+'<div class="eyebrow">SPIRIMON · '+esc(options.label||'THE SEALER’S FRONTIER')+'</div><h2>'+esc(title)+'</h2>'+body+'</section></div>';renderSpiritCanvases($('#modal-root'));$('#modal-root button:not(.modal-close),#modal-root input')?.focus({preventScroll:true});}
function closeModal(){ritual=null;modal=null;document.body.classList.remove('modal-open');$('#modal-root').innerHTML='';keys.clear();if(view==='explore')$('#world')?.focus({preventScroll:true});}
function starters(){starterChoices=Array.from({length:3},(_,n)=>{const r=E.rng(E.hash(s.seed,starterBase,n)),alter=E.pick(E.TYPES.filter(t=>t!==starterBase),r);return register(E.makeSpecies(E.hash(s.seed,'starter',starterBase,n),starterBase,alter,[]));});showModal('Every great bond starts somewhere.','<p>Welcome to Mossveil Crossing. Choose a base type, then one of three spirits offered by the sealing guild. Their second type shapes what makes each one different.</p><label for="sealer-name">Your sealer’s name</label><input id="sealer-name" maxlength="24" value="'+esc(s.player.name==='Sealer'?'':s.player.name)+'" placeholder="What should we call you?"><label for="starter-base">Spirit base type</label><select id="starter-base">'+E.TYPES.map(t=>'<option '+(t===starterBase?'selected':'')+'>'+t+'</option>').join('')+'</select><div class="starter-grid">'+starterChoices.map(sp=>'<button class="starter-choice" data-action="starter" data-value="'+sp.id+'">'+sprite(sp,0,160)+'<h3>'+esc(sp.forms[0])+'</h3>'+chip(sp.base)+chip(sp.alter)+'<p>'+esc(sp.temperament)+' · '+esc(sp.ability)+'</p></button>').join('')+'</div><p class="help-line">Procedural starter art · Connect free local models in Settings for AI-designed future discoveries.</p>',{lock:true,wide:true,kind:'starter',label:'YOUR FIRST SEAL'});}
function chooseStarter(id){const sp=s.species[id];if(!sp||s.starter)return;s.player.name=$('#sealer-name')?.value.trim().slice(0,24)||'Sealer';const i=E.heal(E.makeIndividual(sp,5),sp);i.bond=25;s.spirits.push(i);s.party.push(i.id);s.starter=true;discover(sp);closeModal();save();render();toast(sp.forms[0]+' is now attuned. Walk with WASD; press E to interact.');note('Formed the first bond with '+sp.forms[0]+'.');}
function collectionHTML(){const all=s.spirits.filter(i=>{const sp=spOf(i);return(!search||sp.forms.join(' ').toLowerCase().includes(search)||sp.base.toLowerCase().includes(search)||sp.alter.toLowerCase().includes(search))&&(filter!=='attuned'||s.party.includes(i.id));});return'<div class="page-heading"><div><div class="eyebrow">BONDS BENEATH THE SKIN</div><h1>Your spirits.</h1><p>Many tattoos. Six attuned bonds. A lifetime of discoveries.</p></div><span class="pill">'+s.spirits.length+' sealed · '+s.party.length+' attuned</span></div><div class="notice">'+(safe()?'You’re in a safe place. Rest, train, or change which spirits are attuned.':'Return to a town or guild to change attunement and train. You can change unlocked appearances anywhere outside battle.')+'</div><div class="collection-toolbar"><input class="search" id="spirit-search" placeholder="Search spirits or types…" value="'+esc(search)+'" aria-label="Search spirits"><select id="spirit-filter" aria-label="Filter spirits"><option value="all">All tattoos</option><option value="attuned" '+(filter==='attuned'?'selected':'')+'>Attuned only</option></select>'+action('rest','Rest at the guild','','btn')+'</div><div class="cards">'+(all.length?all.map(i=>{const sp=spOf(i);return'<article class="spirit-card"><span class="card-attuned">'+(s.party.includes(i.id)?'◇ ATTUNED':'RESERVE')+'</span><span class="card-rank">Lv. '+i.level+'</span>'+sprite(sp,i.appearance,160)+'<h3>'+esc(sp.forms[i.appearance])+'</h3>'+chip(sp.base)+chip(sp.alter)+sp.domains.map(d=>'<span class="chip">'+esc(d)+'</span>').join('')+'<p>'+esc(i.nature)+' · '+esc(sp.ability)+'</p>'+hpHTML(i,sp)+action('detail','View bond →',i.id,'btn ghost')+'</article>';}).join(''):'<div class="spirit-empty">Your next bond is waiting out there.</div>')+'</div>';}
function detail(id){const i=s.spirits.find(i=>i.id===id);if(!i)return;const sp=spOf(i),st=E.stats(i,sp);showModal(sp.forms[i.appearance],'<div class="detail-top">'+sprite(sp,i.appearance,180)+'<div><div class="pill gold">Level '+i.level+' · Form '+(i.form+1)+'</div><div style="margin:10px 0">'+chip(sp.base)+chip(sp.alter)+sp.domains.map(d=>'<span class="chip">'+esc(d)+'</span>').join('')+'</div><p>'+esc(i.nature)+' · '+esc(sp.temperament)+'</p><p>Ability: '+esc(sp.ability)+'<br><span class="tiny">'+esc(({Steadfast:'Reduce incoming damage while guarded.',Wildheart:'Stronger physical moves.',Soulweave:'Stronger spiritual moves.','Second Wind':'Recover health once per battle when badly hurt.'})[sp.ability])+'</span><br>Bond '+i.bond+' · '+(s.party.includes(id)?'Attuned':'Resting in a tattoo')+'</p></div></div><p>'+esc(sp.description)+'</p><div class="detail-stats"><div><strong>'+st.hp+'</strong><small>Health</small></div><div><strong>'+st.power+'</strong><small>Combined power</small></div><div><strong>'+st.speed+'</strong><small>Speed</small></div></div>'+hpHTML(i,sp)+'<p class="tiny" style="margin-top:10px">Physical resistance: '+(sp.physicalRes<1?'Resistant':'Normal')+' · Spiritual resistance: '+(sp.spiritualRes<1?'Resistant':'Normal')+'<br>Next transformation: '+(i.form===2?'Final form unlocked':'level '+(i.form===0?16:36)+(sp.evolution==='bond'?' and bond 60':''))+' · XP '+i.xp+' / '+i.level*18+'</p><div class="subheading">APPEARANCE · COSMETIC ONLY</div><div class="form-row">'+sp.forms.map((f,n)=>'<button data-action="appearance" data-value="'+id+':'+n+'" '+(n>i.form?'disabled':'')+' class="'+(i.appearance===n?'selected':'')+'">'+sprite(sp,n,96)+'<small>'+(n>i.form?'Locked':esc(f))+'</small></button>').join('')+'</div><div class="move-list">'+sp.moves.map(m=>'<div><span>'+esc(m.name)+'<small> · '+m.kind+'</small></span><small>Power '+m.power+' · PP '+E.moveCost(m)+' · Speed '+(m.speed>=0?'+':'')+m.speed+'</small></div>').join('')+'</div><div class="btn-row">'+action('attune',s.party.includes(id)?'Unattune':'Attune spirit',id)+action('lead','Make lead spirit',id)+action('train','Train · 25 marks',id)+action('bond','Share offering',id)+'</div><p class="help-line">Design: '+(sp.source==='local-llm'?'local AI model':'procedural prototype')+' · Art: '+(sp.sprites?.length===3?'local image model':'procedural pixel art')+'</p>');}
function attune(id){if(battle)return toast('Finish the battle first.');if(!safe())return toast('Change attunement at a town or guild.');if(s.party.includes(id)){if(s.party.length===1)return toast('Keep at least one spirit attuned.');s.party=s.party.filter(x=>x!==id);}else{if(s.party.length>=6)return toast('Six spirits are already attuned.');s.party.push(id);}save();detail(id);render();}
function training(id){if(!safe())return toast('Train at a town or guild.');if(s.inventory.coins<25)return toast('Training costs 25 guild marks.');const i=s.spirits.find(x=>x.id===id);if(!i)return;s.inventory.coins-=25;i.trained=Math.min(60,i.trained+2);i.bond=Math.min(100,i.bond+3);const result=E.gainXP(i,spOf(i),Math.max(70,i.level*10));save();detail(id);render();toast(result.evolved?'A new transformation awakens!':result.levels?'Training complete. Level '+i.level+'.':'Training strengthens your bond and power.');}
function shareOffering(id){if(battle)return;if(s.inventory.offerings<1)return toast('You need an offering.');const i=s.spirits.find(x=>x.id===id);if(!i)return;s.inventory.offerings--;i.bond=Math.min(100,i.bond+12);const result=E.gainXP(i,spOf(i),0);save();detail(id);render();toast(result.evolved?'Your bond awakens a new transformation.':'Your bond deepens.');}
function rest(){if(!safe())return toast('Rest at a town or guild.');party().forEach(i=>E.heal(i,spOf(i)));s.safe={x:s.player.x,y:s.player.y};save();render();toast('Your attuned spirits are fully restored. This is now your recovery point.');}
function atlasHTML(){const c=E.coord(s.player.x,s.player.y),cells=[],radius=innerWidth<560?2:3;for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){const cx=c.cx+dx,cy=c.cy+dy,reg=s.regions[cx+','+cy];cells.push(reg?.visited?'<button class="atlas-cell '+(!dx&&!dy?'current':'')+'" data-action="region-info" data-value="'+reg.key+'" style="background:'+reg.biome.color+'55"><small>'+cx+', '+cy+(reg.town?' · GUILD':'')+'</small><strong>'+esc(reg.name)+'</strong><small>'+esc(reg.biome.name)+' · Lv. '+reg.danger+'+</small></button>':'<div class="atlas-cell unknown" aria-label="Unexplored region">·</div>');}return'<div class="page-heading"><div><div class="eyebrow">THERE IS ALWAYS ANOTHER TRAIL</div><h1>Your world, unfolding.</h1><p>Discovered places stay where you left them. Walk beyond the edge to find more.</p></div><span class="pill">'+Object.values(s.regions).filter(r=>r.visited).length+' regions mapped</span></div><div class="panel"><div class="atlas-grid">'+cells.join('')+'</div><p class="help-line" style="text-align:center">Your location is outlined in gold. Region danger stays fixed as your spirits grow.</p></div>';}
function journalHTML(){const visited=Object.values(s.regions).filter(r=>r.visited).length,quests=[['discovery','First impressions','Discover five different spirit species, then report to Scholar Elin.',s.seen.length+'/5 species · Reward: 100 marks'],['rival','A friendly rivalry','Defeat Rowan in an organized guild battle.',s.wins+' victories · Reward: guild rank progress'],['explorer','Beyond the familiar','Visit three regions and share your findings with Scholar Elin.',visited+'/3 regions · Reward: 150 marks']];return'<div class="page-heading"><div><div class="eyebrow">NO DESTINY REQUIRED</div><h1>A journey of your own.</h1><p>Small promises, familiar faces, and whatever lies around the next bend.</p></div><span class="pill">Rank '+s.rank+' · '+s.rankXP+' / '+s.rank*100+' renown</span></div><div class="journal-grid"><div class="panel"><div class="section-label">GUILD NOTICES <small>ALL OPTIONAL</small></div>'+quests.map(([id,title,desc,progress])=>'<div class="quest '+(s.quests[id]?'quest-complete':'')+'"><h3>'+(s.quests[id]?'✓ ':'')+title+'</h3><p>'+desc+'</p><small>'+(s.quests[id]?'Completed':progress)+'</small></div>').join('')+'<div class="subheading">PEOPLE YOU KNOW</div>'+['Keeper Iona','Tavi','Rowan','Scholar Elin'].map((name,n)=>{const role=['keeper','merchant','rival','scholar'][n],value=Object.entries(s.friendships).filter(([k])=>k.startsWith(role)).reduce((sum,[,v])=>sum+v,0);return'<div class="friend-row"><span>'+name+'</span><span class="muted">'+(value>15?'Friend':value>3?'Acquaintance':'New face')+' · '+value+'</span></div>';}).join('')+'</div><div class="panel"><div class="section-label">FIELD JOURNAL</div>'+s.notes.slice(0,18).map(n=>'<p class="journal-entry">'+esc(n)+'</p>').join('')+'</div></div>';}

function move(dx,dy){if(modal||battle||view!=='explore'||!s.starter)return;const x=s.player.x+dx,y=s.player.y+dy;s.player.face=dx<0?'left':dx>0?'right':dy<0?'up':'down';const c=E.coord(x,y),n=E.npcs(s.seed,c.cx,c.cy).find(n=>n.x===x&&n.y===y);if(n){talk(n);return;}if(!E.walkable(E.tile(s.seed,x,y),abilityReady('swim'),abilityReady('climb')))return;s.player.x=x;s.player.y=y;s.steps++;discoverRegion();const roamer=nearbyRoamer();if(roamer&&roamer.x===x&&roamer.y===y){approach(roamer);return;}if(E.tile(s.seed,x,y)==='grass'&&s.steps>8&&Math.random()<.075){const reg=currentRegion(),sp=speciesFor(reg,Math.random),form=E.rollForm();startBattle(E.heal(E.makeIndividual(sp,Math.max(2,reg.danger+Math.floor(Math.random()*3)+form*10),form),sp));return;}if(s.steps%75===0)replenish();$('#map-hint').textContent=hint();$('#map-location').textContent=currentRegion().name;$('#map-biome').textContent=currentRegion().biome.name.toUpperCase();save();}
function replenish(){const reg=currentRegion(),group=s.roamers[reg.key]||[];if(group.filter(r=>r.active).length>=5)return;const r=Math.random,sp=speciesFor(reg,r),form=E.rollForm(r);for(let k=0;k<40;k++){const x=reg.cx*48+3+Math.floor(r()*42),y=reg.cy*36+3+Math.floor(r()*30);if(E.walkable(E.tile(s.seed,x,y))&&Math.abs(x-s.player.x)+Math.abs(y-s.player.y)>8){group.push({id:'r-'+Date.now(),x,y,active:true,ind:E.heal(E.makeIndividual(sp,reg.danger+form*10,form),sp)});break;}}}
function interact(){if(modal||battle||!s.starter)return;const drop=s.drops.find(d=>Math.abs(d.x-s.player.x)+Math.abs(d.y-s.player.y)<=1);if(drop){for(const key of['seals','offerings','tonics','ethers'])s.inventory[key]+=drop.items[key]||0;s.drops=s.drops.filter(d=>d!==drop);save();render();toast('Recovered your dropped supplies.');return;}const n=nearbyNPC();if(n)return talk(n);const r=nearbyRoamer();if(r)return approach(r);if(safe())return showModal('A moment to breathe.','<p>The guild lamps are lit. Rest your spirits, adjust your tattoos, or prepare for the next trail.</p><div class="btn-row">'+action('rest-close','Rest and recover')+action('collection-close','Manage tattoos')+'</div>');toast('Move closer to a person or roaming spirit, then press E.');}
function approach(roamer){if(!roamer.active)return;const sp=spOf(roamer.ind);discover(sp);showModal('A spirit watches you.','<div class="detail-top">'+sprite(sp,roamer.ind.appearance,180)+'<div><h3>'+esc(sp.forms[roamer.ind.appearance])+'</h3>'+chip(sp.base)+chip(sp.alter)+'<p>Level '+roamer.ind.level+' · '+esc(sp.temperament)+'</p></div></div><p>'+esc(sp.description)+'</p><p style="margin-top:12px">You could challenge it, or give it a reason to trust you.</p><div class="btn-row">'+action('wild-battle','Challenge',roamer.id,'btn primary')+action('offer','Offer food · 1 offering',roamer.id)+action('observe','Approach gently',roamer.id)+action('close','Leave in peace','','btn ghost')+'</div>');save();}
function findRoamer(id){return Object.values(s.roamers).flat().find(r=>r.id===id);}
function cooperate(id,useOffering){const r=findRoamer(id);if(!r?.active)return;const sp=spOf(r.ind);if(useOffering){if(!s.inventory.offerings)return toast('Buy offerings from Tavi.');s.inventory.offerings--;}r.trust??=0;r.trust+=useOffering?2:1;if(Math.random()<(useOffering?.7:.35)||r.trust>=3){closeModal();startRitual(r.ind,id);}else{save();showModal('A little patience.','<div style="text-align:center">'+sprite(sp,r.ind.appearance,160)+'</div><p>'+esc(sp.forms[r.ind.appearance])+' keeps its distance, but seems interested. Your patience is beginning to matter.</p><div class="btn-row">'+action('observe','Wait quietly',id)+action('offer','Offer food',id)+action('wild-battle','Challenge',id)+action('close','Leave','','btn ghost')+'</div>');}}
function startRitual(ind,roamer){if(s.inventory.seals<1)return toast('You need a seal catalyst from Tavi.');ritual={ind:structuredClone(ind),roamer,start:performance.now(),progress:0};showModal('Steady the bond.','<p>The spirit is willing. Align the pulse with the golden window to anchor its tattoo.</p><div class="ritual-sigil">◇</div><div class="timing-track"><div class="timing-target"></div><div class="timing-cursor" id="ritual-cursor"></div></div><div class="btn-row" style="justify-content:center">'+action('seal-pulse',s.settings.timing==='off'?'Complete the seal':'Anchor the seal · SPACE','','btn primary')+'</div><p class="help-line" style="text-align:center">'+(s.settings.timing==='off'?'Timing assistance enabled. This seal will succeed.':'Misses do not consume a catalyst. Retry at your own pace.')+'</p>',{kind:'ritual'});}
function sealPulse(){if(!ritual)return;const ok=s.settings.timing==='off'||ritual.progress>=.39&&ritual.progress<=.61;if(!ok)return toast('The pulse slips. Breathe, and try again.');const{ind,roamer}=ritual;ritual=null;s.inventory.seals--;capture(ind,roamer);closeModal();render();}
function capture(ind,roamer){const sp=spOf(ind);if(s.spirits.some(i=>i.id===ind.id))return;ind.bond=25;E.heal(ind,sp);s.spirits.push(ind);if(s.party.length<6)s.party.push(ind.id);s.captured++;discover(sp);if(roamer)removeRoamer(roamer);note('Sealed a bond with '+sp.forms[ind.appearance]+'.');renown(20);save();toast(sp.forms[ind.appearance]+' is sealed into a new tattoo.');}
function renown(value){s.rankXP+=value;while(s.rank<6&&s.rankXP>=s.rank*100){s.rankXP-=s.rank*100;s.rank++;note('Earned guild rank '+s.rank+': '+rankName()+'.');}}
function talk(n){s.friendships[n.id]??=0;const intro=s.friendships[n.id]>15?'It’s good to see you again, '+s.player.name+'. ':'';let body='';if(n.role==='keeper')body='<p>'+esc(intro)+'A seal is a promise, not a prison. There’s room for many bonds beneath your skin, but only six can be awake at once.</p><div class="btn-row">'+action('rest-close','Restore spirits','','btn primary')+action('collection-close','Attune tattoos')+action('chat','Share a story',n.id)+'</div>';
if(n.role==='merchant')body='<p>'+esc(intro)+'A full pack makes for a longer trail. What do you need?</p><p style="margin-top:10px;color:var(--gold)">'+s.inventory.coins+' guild marks available</p><div class="btn-row">'+action('buy','Seal catalyst · 12 marks','seals')+action('buy','Offering · 8 marks','offerings')+action('buy','Tonic · 10 marks','tonics')+action('buy','Soul draught · 16 marks','ethers')+action('buy','Improve seals · 100 marks','quality')+'</div><div class="modal-section"><p>Bring three spare catalysts and I’ll trade you a tonic.</p><div class="btn-row">'+action('trade-items','Trade 3 catalysts → 1 tonic')+action('chat','Share a story',n.id)+'</div></div>';
if(n.role==='rival')body='<p>'+esc(intro)+'I’ve been training. Ready for a friendly match? Guild matches follow your rank, so neither of us gets too comfortable.</p><div class="btn-row">'+action('trainer','Battle Rowan','','btn primary')+action('npc-trade','Trade spirits')+action('chat','Share a story',n.id)+'</div>';
if(n.role==='scholar')body='<p>'+esc(intro)+'Each spirit is a question the world hasn’t answered yet. Bring me your discoveries; I’ll help fund the next expedition.</p><div class="btn-row">'+action('claim','Report five species','discovery')+action('claim','Report three regions','explorer')+action('chat','Share a story',n.id)+'</div>';s.activeNPC=n;showModal(n.name,body,{label:n.role==='merchant'?'TRAIL SUPPLIES':'A FAMILIAR FACE'});}
function chat(id){const last=s.chatSteps?.[id]??-100;if(s.steps-last<10)return toast('You’ve caught up for now. Come back after exploring.');s.chatSteps??={};s.chatSteps[id]=s.steps;s.friendships[id]=(s.friendships[id]||0)+4;renown(5);note('Shared a story with '+s.activeNPC.name+'.');save();toast('Your friendship with '+s.activeNPC.name+' grows.');}
function buy(item){const cost={seals:12,offerings:8,tonics:10,ethers:16,quality:100}[item];if(!cost)return;if(s.inventory.coins<cost)return toast('Not enough guild marks.');if(item==='quality'&&s.inventory.quality>=3)return toast('Your seal catalysts are already masterwork quality.');s.inventory.coins-=cost;s.inventory[item]=(s.inventory[item]||0)+1;save();talk(s.activeNPC);render();toast(item==='quality'?'Seal quality improved.':'Supplies added to your bag.');}
function claim(which){const ready=which==='discovery'?s.seen.length>=5:Object.values(s.regions).filter(r=>r.visited).length>=3;if(s.quests[which])return toast('You’ve already received this reward.');if(!ready)return toast('Keep exploring. Your discoveries will be here when you return.');s.quests[which]=true;const amount=which==='discovery'?100:150;s.inventory.coins+=amount;renown(50);note('Completed '+(which==='discovery'?'First impressions':'Beyond the familiar')+'.');save();talk(s.activeNPC);render();toast('Report accepted. +'+amount+' marks and 50 renown.');}
function tradeSpirit(){if(battle||!safe())return;const spare=s.spirits.filter(i=>!s.party.includes(i.id));if(!spare.length)return toast('Keep a spirit in reserve to offer Rowan a trade.');const offer=spare[0],sp=speciesFor(currentRegion(),Math.random),incoming=E.heal(E.makeIndividual(sp,Math.max(3,offer.level)),sp);s.trade={out:offer.id,incoming};showModal('A fair exchange.','<p>Rowan offers '+esc(sp.forms[0])+' (Lv. '+incoming.level+') for your reserve '+esc(spOf(offer).forms[offer.appearance])+'.</p><div style="text-align:center">'+sprite(sp,0,160)+'</div><div class="btn-row">'+action('confirm-trade','Accept trade','','btn primary')+action('close','Keep my spirit','','btn ghost')+'</div>');}
function bag(){showModal('Ready for the trail.','<p>Your supplies travel with you. Tavi sells more in town.</p><div class="bag-grid"><div><strong>'+s.inventory.seals+'</strong><small>Seal catalysts</small></div><div><strong>'+s.inventory.offerings+'</strong><small>Offerings</small></div><div><strong>'+s.inventory.tonics+'</strong><small>Tonics</small></div></div><p style="margin-top:20px">Guild marks: '+s.inventory.coins+' · Seal quality: '+['','Standard','Refined','Masterwork'][s.inventory.quality]+'</p><div class="btn-row">'+action('tonic','Use tonic on lead spirit')+action('ether','Restore shared PP · '+(s.inventory.ethers||0))+action('export','Export save backup','','btn ghost')+'</div><p class="help-line">Tonics restore half a spirit’s maximum health. During battle, using one takes your action.</p>');}
function useTonic(){if(!s.inventory.tonics)return toast('No tonics remaining.');const i=battle?s.spirits.find(x=>x.id===battle.ally):lead();if(!i)return toast('No active spirit can receive a tonic.');const max=E.stats(i,spOf(i)).hp;if(i.hp>=max)return toast('Your spirit is already healthy.');s.inventory.tonics--;i.hp=Math.min(max,i.hp+Math.ceil(max*.5));closeModal();if(battle)enemyOnly('You use a tonic.');else{save();render();toast('Your lead spirit recovers health.');}}
function startBattle(enemy,roamer=null,trainer=false){const ally=lead();if(!ally)return toast('Your spirits need rest at the guild.');closeModal();party().forEach(i=>i.secondWindUsed=false);enemy.secondWindUsed=false;discover(spOf(enemy));battle={enemy:structuredClone(enemy),ally:ally.id,roamer,trainer,round:1,log:[trainer?'Rowan challenges you to a guild match.':'A wild '+spOf(enemy).forms[enemy.appearance]+' draws near.'],supportUsed:false,credits:{a:0,b:0}};borrow=0;commit=ally.commit;style='normal';selectedMove=0;view='explore';save();render();}
function trainerBattle(){const r=E.rng(E.hash(s.seed,'rowan',s.rank,s.wins)),sp=speciesFor(currentRegion(),r);startBattle(E.heal(E.makeIndividual(sp,4+s.rank*3,0,r),sp),null,true);}
function battleHTML(){const ally=s.spirits.find(i=>i.id===battle.ally),asp=spOf(ally),enemy=battle.enemy,esp=spOf(enemy);return'<div class="page-heading"><div><div class="eyebrow">'+(battle.trainer?'FRIENDLY GUILD MATCH':'A MEETING IN THE WILD')+'</div><h1>'+esc(battle.trainer?'A worthy rival.':'A bond or a battle?')+'</h1><p>Choose your move, style, and commitment. One baseline action each round. Borrow more at a cost.</p></div><span class="round-tag">ROUND '+battle.round+'</span></div><div class="battle-arena"><canvas id="battle-canvas" width="1000" height="350" aria-label="Spirit battle"></canvas><div class="combatant enemy"><h3>'+esc(esp.forms[enemy.appearance])+' <small>Lv. '+enemy.level+'</small></h3>'+hpHTML(enemy,esp)+'<div>'+chip(esp.base)+chip(esp.alter)+'</div></div><div class="combatant ally"><h3>'+esc(asp.forms[ally.appearance])+' <small>Lv. '+ally.level+'</small></h3>'+hpHTML(ally,asp)+'<div>'+chip(asp.base)+chip(asp.alter)+'</div></div></div><div class="battle-grid"><section class="panel"><div class="section-label">CHOOSE YOUR ACTION <small id="speed-hint">'+speedHint()+'</small></div><div class="battle-moves">'+asp.moves.map((m,n)=>'<button class="move-button '+(n===selectedMove?'selected':'')+'" data-action="move-select" data-value="'+n+'" title="'+esc(m.desc)+'"><strong>'+esc(m.name)+'</strong><small>'+esc(m.type)+' · '+m.kind+' · Power '+m.power+' · PP '+E.moveCost(m)+' · Speed '+(m.speed>=0?'+':'')+m.speed+'</small></button>').join('')+'</div><div class="style-selector">'+['agile','normal','strong'].map(t=>'<button class="'+(style===t?'selected':'')+'" data-action="style" data-value="'+t+'">'+t[0].toUpperCase()+t.slice(1)+(t==='agile'?' · Fast':t==='strong'?' · Heavy':' · Balanced')+'</button>').join('')+'</div>'+tempoHTML(ally,asp)+'<div class="commitment-label"><span>← Preserve defense</span><span>Commit to attack →</span></div><input class="commitment" id="commitment" type="range" min="0" max="100" value="'+Math.round(commit*100)+'" aria-label="Attack commitment"><p class="tiny muted">Your previous allocation protects you until your spirit acts.</p><div class="btn-row">'+action('battle-act','Commit action →','','btn primary')+(!battle.trainer?action('battle-seal','Attempt seal · '+s.inventory.seals):'')+action('battle-switch','Switch spirit')+(!battle.trainer?action('flee','Retreat','','btn ghost'):'')+'</div><div class="battle-support">'+action('tonic','Tonic · '+s.inventory.tonics,'','btn ghost small')+action('ether','Soul draught · '+(s.inventory.ethers||0),'','btn ghost small')+action('support','Sealer’s ward'+(battle.supportUsed?' · used':''),'','btn ghost small')+'</div></section><aside class="panel"><div class="section-label">BATTLE RECORD</div><div class="battle-log">'+battle.log.slice(-12).map(t=>'<p>'+esc(t)+'</p>').join('')+'</div><div class="field-note"><h3>Read the rhythm.</h3><p>Agile strikes are faster and lighter. Strong strikes hit harder but act later. Neither changes your attack commitment. Borrowing actions gives your opponent equal bonus actions next round.</p></div></aside></div>';}
function speedHint(){if(!battle)return'';const i=s.spirits.find(i=>i.id===battle.ally),p=spOf(i).moves[selectedMove].speed+E.STYLES[style].speed;return p>=12?'LIKELY FAST':p<=-12?'LIKELY SLOW':'NORMAL PACE';}
function drawBattle(){const canvas=$('#battle-canvas');if(!canvas||!battle)return;const c=canvas.getContext('2d');c.clearRect(0,0,1000,350);c.fillStyle='#466e4866';for(let x=0;x<1000;x+=48){c.fillRect(x,210+E.hash(x)%35,26,3);c.fillRect(x+13,300+E.hash(x,3)%30,14,2);}c.fillStyle='#384e3444';c.beginPath();c.ellipse(265,293,150,28,0,0,Math.PI*2);c.fill();c.fillStyle='#a1ae7966';c.beginPath();c.ellipse(740,190,135,25,0,0,Math.PI*2);c.fill();const ally=s.spirits.find(i=>i.id===battle.ally);drawSpirit(c,spOf(ally),ally.appearance,150,75,240,true);drawSpirit(c,spOf(battle.enemy),battle.enemy.appearance,640,5,205);}
function enemyChoice(){const en=battle.enemy,sp=spOf(en);let move=E.pick(sp.moves,Math.random);if(en.hp<E.stats(en,sp).hp*.3&&sp.moves.some(m=>m.effect==='heal')&&Math.random()<.65)move=sp.moves.find(m=>m.effect==='heal');return{move,style:E.pick(['normal','normal','agile','strong'],Math.random),commit:.3+Math.random()*.5,borrow:battle.trainer&&s.rank>=2&&en.pp>25&&Math.random()<.18?1:0};}
function doBattle(){if(!battle)return;const i=s.spirits.find(i=>i.id===battle.ally);const result=E.resolveTempoRound(i,spOf(i),battle.enemy,spOf(battle.enemy),{move:spOf(i).moves[selectedMove],style,commit,borrow},enemyChoice(),battle.credits||{a:0,b:0});battle.log.push(...result.log);battle.credits=result.nextCredits;if(result.nextCredits.b)battle.log.push('Your opponent receives '+result.nextCredits.b+' bonus action(s) next round.');if(result.nextCredits.a)battle.log.push('Your spirit receives '+result.nextCredits.a+' bonus action(s) next round.');borrow=0;battle.round++;finishRound();}
function enemyOnly(message){if(!battle)return;if(message)battle.log.push(message);const i=s.spirits.find(i=>i.id===battle.ally),c=enemyChoice();for(let n=0;n<1+(battle.credits?.b||0)&&i.hp>0;n++)battle.log.push(...E.executeAction(battle.enemy,spOf(battle.enemy),i,spOf(i),c.move,c.style,c.commit,Math.random,1+n*.5));battle.credits={a:0,b:0};borrow=0;battle.round++;finishRound();}
function finishRound(){if(battle.enemy.hp<=0){winBattle();return;}const i=s.spirits.find(i=>i.id===battle.ally);if(i.hp<=0){const next=party().find(p=>p.hp>0);if(!next){loseBattle();return;}battle.log.push(spOf(i).forms[i.appearance]+' retreats into its seal. '+spOf(next).forms[next.appearance]+' steps forward.');battle.ally=next.id;commit=next.commit;}save();render();}
function winBattle(){const won=battle,ally=s.spirits.find(i=>i.id===won.ally),sp=spOf(ally),xp=won.enemy.level*(won.trainer?35:24),result=E.gainXP(ally,sp,xp);ally.bond=Math.min(100,ally.bond+4);s.wins++;const reward=won.trainer?35+s.rank*12:8+won.enemy.level*2;s.inventory.coins+=reward;renown(won.trainer?45:12);if(won.trainer&&!s.quests.rival){s.quests.rival=true;s.friendships['rival-0,0']=(s.friendships['rival-0,0']||0)+8;}if(won.roamer)removeRoamer(won.roamer);battle=null;note('Won '+(won.trainer?'a guild match':'a wild battle')+' with '+sp.forms[ally.appearance]+'.');save();render();showModal(result.evolved?'A new form awakens.':'A bond grows stronger.','<div style="text-align:center">'+sprite(sp,ally.appearance,180)+'</div><p>You earned '+reward+' guild marks and '+xp+' experience.'+(result.levels?' '+esc(sp.forms[ally.appearance])+' reached level '+ally.level+'.':'')+(result.evolved?' Previous forms remain available as cosmetic appearances.':'')+'</p><div class="btn-row">'+action('close','Continue exploring','','btn primary')+'</div>');}
function loseBattle(){const items={seals:Math.floor(s.inventory.seals/3),offerings:Math.floor(s.inventory.offerings/3),tonics:Math.floor(s.inventory.tonics/3),ethers:Math.floor((s.inventory.ethers||0)/3)};for(const k of Object.keys(items))s.inventory[k]-=items[k];s.drops.push({x:s.player.x,y:s.player.y,items});const cost=Math.min(s.inventory.coins,20+s.rank*5);s.inventory.coins-=cost;s.player.x=s.safe.x;s.player.y=s.safe.y;party().forEach(i=>E.heal(i,spOf(i)));battle=null;save();render();showModal('Back beneath the guild lamps.','<p>A passing sealer helped you return to safety. Recovery cost '+cost+' marks. Your dropped supplies are waiting where you fell; press E nearby to retrieve them.</p><div class="btn-row">'+action('close','Rest, then try again','','btn primary')+'</div>');}
function battleSeal(){if(!battle||battle.trainer)return;if(s.inventory.seals<1)return toast('No seal catalysts remaining.');s.inventory.seals--;const en=battle.enemy,sp=spOf(en),chance=E.sealChance(en,sp,s.inventory.quality);if(Math.random()<chance){const roamer=battle.roamer;battle=null;capture(en,roamer);save();render();showModal('A new bond, beneath the skin.','<div style="text-align:center">'+sprite(sp,en.appearance,180)+'</div><p>'+esc(sp.forms[en.appearance])+' has become a tattoo seal. '+(s.party.includes(en.id)?'Your new companion is attuned.':'Visit a safe place to attune this spirit.')+'</p><div class="btn-row">'+action('close','Continue','','btn primary')+'</div>');}else enemyOnly('The seal flickers and breaks. Weaken or hinder the spirit to improve your chances.');}
function switchBattle(){const options=party().filter(i=>i.hp>0&&i.id!==battle.ally);if(!options.length)return toast('No other healthy attuned spirits.');showModal('Call another bond.','<p>Switching takes your action for this round.</p><div class="btn-row">'+options.map(i=>action('switch-to',esc(spOf(i).forms[i.appearance])+' · Lv. '+i.level,i.id)).join('')+'</div>');}
function profile(){showModal(s.player.name+', '+rankName(),'<p>A sealer of the '+currentRegion().biome.name+'. Your story is yours to write.</p><div class="detail-stats"><div><strong>'+s.rank+'</strong><small>Guild rank</small></div><div><strong>'+s.wins+'</strong><small>Battles won</small></div><div><strong>'+s.steps+'</strong><small>Steps taken</small></div></div><p>Renown: '+s.rankXP+' / '+s.rank*100+'<br>Wade: rank 2 and an Elemental, Ooze, or Water spirit. Climb: rank 3 and a Beast, Giant, or Construct.<br>Once per battle, Sealer’s Ward protects your spirit and consumes your action.</p><label for="rename">Sealer name</label><input id="rename" value="'+esc(s.player.name)+'" maxlength="24"><div class="btn-row">'+action('rename','Save name')+'</div>');}

function exportSave(){const payload={format:'spirimon-backup',version:E.VERSION,exportedAt:new Date().toISOString(),save:{...s,battle},library:Object.values(library)},blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spirimon-'+s.seed+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save backup exported.');}
async function importSave(file){if(!file)return;if(file.size>150*1024*1024)return toast('Backup is too large.');try{const data=JSON.parse(await file.text());if(data.format!=='spirimon-backup'||data.version!==1||!data.save?.player||!Array.isArray(data.save.spirits)||!data.save.species||typeof data.save.seed!=='string')throw Error('Not a Spirimon backup.');const next=data.save;if(!Number.isInteger(next.player.x)||!Number.isInteger(next.player.y)||!Array.isArray(next.party)||next.party.length>6)throw Error('Invalid player or party data.');for(const i of next.spirits){if(!next.species[i.species]||!Number.isFinite(i.hp)||!Number.isInteger(i.form)||i.form<0||i.form>2)throw Error('Invalid spirit data.');}for(const sp of Object.values(next.species)){if(!E.TYPES.includes(sp.base)||!E.TYPES.includes(sp.alter)||sp.base===sp.alter||sp.forms?.length!==3||sp.moves?.length!==4)throw Error('Invalid species data.');}await dbPut('saves',structuredClone(s),'before-import');s=next;for(const sp of data.library||[])if(sp?.id&&E.TYPES.includes(sp.base)&&E.TYPES.includes(sp.alter))library[sp.id]=sp;for(const sp of Object.values(s.species))register(sp);battle=s.battle||null;closeModal();discoverRegion();await persist();render();toast('Backup restored. Your previous world was kept as a recovery save.');}catch(e){toast('Could not import: '+e.message);}}
function settings(){showModal('Your world. Your device.','<p>Spirimon saves locally in this browser. Export backups before clearing browser data or switching browsers. No account or paid AI service is needed.</p><label for="layout-setting">Play layout</label><select id="layout-setting"><option value="auto">Automatic · emulator controls on phones</option><option value="emulator">Emulator · landscape touch controls</option><option value="desktop">Desktop · exploration dashboard</option></select><div class="btn-row">'+action('fullscreen','Fullscreen / landscape')+'</div><label for="timing-setting">Sealing challenge timing</label><select id="timing-setting"><option value="normal" '+(s.settings.timing==='normal'?'selected':'')+'>Normal</option><option value="slow" '+(s.settings.timing==='slow'?'selected':'')+'>Slower pulse</option><option value="off" '+(s.settings.timing==='off'?'selected':'')+'>No timing requirement</option></select><div class="btn-row">'+action('export','Export backup')+'<label class="btn" style="margin:0;cursor:pointer">Import backup<input type="file" id="import-file" accept=".json" hidden></label>'+action('restore-backup','Restore previous world','','btn ghost')+'</div><div class="modal-section"><p><a class="btn ghost" href="./Spirimon.html" download>Download standalone game</a></p><p class="help-line">For the optional local AI companion, download the full source package from the project folder.</p></div><div class="modal-section"><h3>Free local AI</h3><p style="margin-top:8px">The optional companion connects to Ollama for spirit designs and a local Stable Diffusion WebUI API for sprites. Without models, procedural spirits keep the game playable.</p><label><input type="checkbox" id="ai-enabled" '+(s.settings.aiEnabled?'checked':'')+'> Generate future discoveries with local AI</label><label for="ai-model">Installed text model</label><select id="ai-model"><option value="">Detect installed models first</option></select><div class="btn-row">'+action('check-ai','Check companion')+action('generate-now','Queue a new lineage')+'</div><div id="ai-status" class="settings-status">Companion: '+(aiStatus?esc(aiStatus.message):'not checked')+'<br>Queue: '+queue.length+' lineages'+(busy?' · generating':'')+'</div><p class="help-line">AI-created lineages enter the library only after their text and all three sprites finish. Already discovered spirits never change.</p></div><div class="modal-section"><h3>Begin another world</h3><p>Your species library stays. Export your current save first; a recovery copy is also retained.</p><label for="new-seed">World seed (optional)</label><input id="new-seed" maxlength="40" placeholder="A word, number, or leave blank"><div class="btn-row">'+action('new-world','Prepare a new world','','btn danger')+'</div></div>',{kind:'settings'});if(aiStatus?.models)fillModels();$('#layout-setting').value=s.settings.layout||'auto';}
function fillModels(){const select=$('#ai-model');if(!select)return;select.innerHTML=(aiStatus.models||[]).map(m=>'<option '+(m===s.settings.model?'selected':'')+'>'+esc(m)+'</option>').join('')||'<option value="">No text models installed</option>';}
async function checkAI(){const out=$('#ai-status');if(out)out.textContent='Checking local companion…';try{const response=await fetch(COMPANION+'/api/status',{signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error('Companion returned '+response.status);aiStatus=await response.json();aiStatus.message=(aiStatus.models.length?'Text models ready':'No Ollama model found')+' · '+(aiStatus.imageReady?'Image API ready':'Image API not connected');fillModels();if(out)out.textContent=aiStatus.message+' · queue '+queue.length;}catch(err){aiStatus={message:'Companion offline. Run Start-Spirimon.cmd from the downloaded game.',models:[],imageReady:false};if(out){out.textContent=aiStatus.message;out.classList.add('error');}}}
async function processQueue(){if(busy||!s.settings.aiEnabled||!queue.length)return;busy=true;const id=queue.shift(),original=library[id];if(!original){busy=false;return;}try{const model=s.settings.model||aiStatus?.models?.[0];if(!model)throw Error('Choose an installed text model in Settings.');const existing=Object.values(library).filter(p=>p.base===original.base&&p.alter===original.alter).slice(-6).map(p=>({forms:p.forms,description:p.description}));const res=await fetch(COMPANION+'/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({species:original,model,existing}),signal:AbortSignal.timeout(900000)});const data=await res.json();if(!res.ok)throw Error(data.error||'Local generation failed');let sp=E.validateSpecies(data,original);if(!Array.isArray(data.sprites)||data.sprites.length!==3||data.sprites.some(v=>typeof v!=='string'||!v.startsWith('data:image/png;base64,')))throw Error('All three sprite images are required.');sp={...sp,id:'ai-'+original.id+'-'+E.hash(data.forms.join('')),sprites:data.sprites};register(sp);note('A new local-AI lineage is ready in the library: '+sp.forms[0]+'.');save();toast('Local AI finished a new three-form lineage.');}catch(e){toast('AI generation paused: '+e.message);s.settings.aiEnabled=false;save();}finally{busy=false;if(modal==='settings')settings();}}
function drawWorld(time){const canvas=$('#world');if(!canvas||view!=='explore'||battle)return;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const ox=s.player.x-15,oy=s.player.y-10;for(let yy=-1;yy<=20;yy++)for(let xx=-1;xx<=30;xx++){const x=ox+xx,y=oy+yy,reg=E.region(s.seed,Math.floor(x/48),Math.floor(y/36));drawTile(c,E.tile(s.seed,x,y),xx*32,yy*32,E.hash(s.seed,x,y),reg.biome.kind);}const pc=E.coord(s.player.x,s.player.y);for(let cy=pc.cy-1;cy<=pc.cy+1;cy++)for(let cx=pc.cx-1;cx<=pc.cx+1;cx++){const reg=E.region(s.seed,cx,cy);if(reg.town){for(const[lx,ly,guild]of[[19,11,true],[28,12,false],[29,22,false]]){const x=(cx*48+lx-ox)*32,y=(cy*36+ly-oy)*32;if(x>-180&&x<1020&&y>-150&&y<700)drawBuilding(c,x,y,guild);}for(const n of E.npcs(s.seed,cx,cy)){const x=(n.x-ox)*32,y=(n.y-oy)*32;drawPerson(c,x,y-5,n.role);if(Math.abs(n.x-s.player.x)+Math.abs(n.y-s.player.y)<=2){c.fillStyle='#ecd291';c.font='bold 14px Segoe UI';c.textAlign='center';c.fillText('E',x+16,y-12);}}}for(const r of s.roamers[cx+','+cy]||[]){if(!r.active)continue;const x=(r.x-ox)*32,y=(r.y-oy)*32;if(x<-70||x>1000||y<-70||y>680)continue;drawSpirit(c,spOf(r.ind),r.ind.appearance,x-13,y-29+Math.sin(time/500+E.hash(r.id)%20)*2,58);if(r.ind.form>0){c.fillStyle='#e5cb86';c.fillRect(x+25,y-16,3,3);}}}for(const d of s.drops){const x=(d.x-ox)*32,y=(d.y-oy)*32;c.fillStyle='#d2b17b';c.fillRect(x+9,y+9,14,15);c.fillStyle='#725b3b';c.fillRect(x+14,y+6,4,6);}drawPerson(c,480,315,'player',time);const l=lead();if(l)drawSpirit(c,spOf(l),l.appearance,442,324,43);const g=c.createRadialGradient(480,320,160,480,320,650);g.addColorStop(0,'#b8d5a000');g.addColorStop(1,'#0e30244d');c.fillStyle=g;c.fillRect(0,0,960,640);for(let i=0;i<15;i++){c.globalAlpha=.25+Math.sin(time/700+i)*.2;c.fillStyle='#f2e4a4';c.fillRect((i*137+time*.008)%960,(i*83+Math.sin(time/1400+i)*18)%640,2,2);}c.globalAlpha=1;const coord=$('#map-coords');if(coord)coord.textContent=s.player.x+' / '+s.player.y;}
function tick(time){const delta=Math.min(1000,time-lastTime);lastTime=time;if(loaded){s.playTime+=delta;if(!modal&&!battle&&view==='explore'&&time-lastStep>140){const key=[...keys].find(k=>['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k));if(key){const dir={w:[0,-1],arrowup:[0,-1],a:[-1,0],arrowleft:[-1,0],s:[0,1],arrowdown:[0,1],d:[1,0],arrowright:[1,0]}[key];move(...dir);lastStep=time;}}if(ritual){ritual.progress=(Math.sin((time-ritual.start)/(s.settings.timing==='slow'?1800:950)*Math.PI)+1)/2;const cursor=$('#ritual-cursor');if(cursor)cursor.style.left=ritual.progress*99+'%';}drawWorld(time);}requestAnimationFrame(tick);}
document.addEventListener('click',async ev=>{const btn=ev.target.closest('[data-action]');if(!btn||btn.disabled)return;ev.preventDefault();const a=btn.dataset.action,v=btn.dataset.value;switch(a){
case'emu-a':interact();break;
case'emu-b':bag();break;
case'fullscreen':await enterFullscreen();break;
case'portrait-play':s.settings.portraitAllowed=true;applyLayout();save();break;
case'view':if(battle&&v!=='explore')return toast('Finish the encounter first.');view=v;render();break;
case'close':closeModal();break;
case'starter':chooseStarter(v);break;
case'step':move(...{up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[v]);break;
case'interact':interact();break;
case'detail':detail(v);break;
case'attune':attune(v);break;
case'lead':if(battle)return toast('Use Switch spirit during battle.');if(!s.party.includes(v))return toast('Attune this spirit first.');s.party=[v,...s.party.filter(x=>x!==v)];save();detail(v);render();break;
case'appearance':{if(battle)return toast('Change appearance outside battle.');const[id,n]=v.split(':'),i=s.spirits.find(x=>x.id===id);if(i&&Number(n)<=i.form){i.appearance=Number(n);save();detail(id);render();}break;}
case'train':training(v);break;
case'bond':shareOffering(v);break;
case'rest':rest();break;
case'rest-close':closeModal();rest();break;
case'collection-close':closeModal();view='spirits';render();break;
case'bag':bag();break;
case'offer':cooperate(v,true);break;
case'observe':cooperate(v,false);break;
case'wild-battle':{const r=findRoamer(v);if(r?.active)startBattle(r.ind,v);break;}
case'seal-pulse':sealPulse();break;
case'chat':chat(v);break;
case'buy':buy(v);break;
case'claim':claim(v);break;
case'trainer':trainerBattle();break;
case'npc-trade':tradeSpirit();break;
case'confirm-trade':{if(!s.trade)return;const{out,incoming}=s.trade;if(s.party.includes(out))return;s.spirits=s.spirits.filter(i=>i.id!==out);s.spirits.push(incoming);discover(spOf(incoming));delete s.trade;save();closeModal();render();toast('The exchange is complete. A new spirit rests in your tattoos.');break;}
case'trade-items':if(s.inventory.seals<3)return toast('You need three seal catalysts.');s.inventory.seals-=3;s.inventory.tonics++;save();talk(s.activeNPC);render();toast('Trade complete.');break;
case'move-select':selectedMove=Number(v);render();break;
case'style':style=v;render();break;
case'borrow':borrow=Number(v);render();break;
case'ether':useEther();break;
case'battle-act':doBattle();break;
case'battle-seal':battleSeal();break;
case'battle-switch':switchBattle();break;
case'switch-to':{if(!battle)return;const i=party().find(i=>i.id===v&&i.hp>0);if(!i)return;battle.ally=v;commit=i.commit;selectedMove=0;closeModal();enemyOnly('You call '+spOf(i).forms[i.appearance]+' into battle.');break;}
case'tonic':useTonic();break;
case'support':if(!battle||battle.supportUsed)return toast('Sealer’s Ward can be used once per battle.');battle.supportUsed=true;s.spirits.find(i=>i.id===battle.ally).ward=true;enemyOnly('Your tattoo glows. Sealer’s Ward softens the incoming blow.');break;
case'flee':if(!battle||battle.trainer)return;battle=null;save();render();toast('You withdraw safely.');break;
case'settings':settings();break;
case'profile':profile();break;
case'rename':s.player.name=$('#rename').value.trim().slice(0,24)||'Sealer';save();closeModal();render();break;
case'export':exportSave();break;
case'check-ai':await checkAI();break;
case'generate-now':{if(!s.settings.aiEnabled)return toast('Enable local AI generation first.');const sp=speciesFor(currentRegion(),Math.random);if(!queue.includes(sp.id))queue.push(sp.id);toast('Lineage queued. All three forms must finish before entering the AI library.');processQueue();break;}
case'new-world':{if(battle)return toast('Finish the battle first.');s.pendingSeed=$('#new-seed').value.trim();showModal('Start a new journey?','<p>Your current world will be retained as a recovery copy. Export a backup too if you want to keep it permanently. Your shared spirit library stays available.</p><div class="btn-row">'+action('confirm-new','Start new world','','btn danger')+action('export','Export current world')+action('close','Cancel','','btn ghost')+'</div>');break;}
case'confirm-new':{await dbPut('saves',structuredClone(s),'before-import');const seed=s.pendingSeed;s=E.newGame(seed||undefined);battle=null;queue=[];view='explore';closeModal();discoverRegion();render();starters();save();break;}
case'restore-backup':{const backup=await dbGet('saves','before-import');if(!backup)return toast('No recovery world is stored yet.');const current=structuredClone(s);s=backup;battle=s.battle||null;await dbPut('saves',current,'before-import');closeModal();discoverRegion();save();render();toast('Previous world restored.');break;}
case'region-info':{const r=s.regions[v];showModal(r.name,'<p>'+esc(r.biome.desc)+'<br>Biome: '+esc(r.biome.name)+'<br>Stable danger: level '+r.danger+' and above<br>'+(r.town?'A guild settlement offers recovery, supplies, and familiar faces.':'Wilderness region. Follow the crossing trails to keep exploring.')+'</p>');break;}
}});
document.addEventListener('input',ev=>{if(ev.target.id==='commitment')commit=Number(ev.target.value)/100;if(ev.target.id==='spirit-search'){const pos=ev.target.selectionStart;search=ev.target.value.toLowerCase();render();$('#spirit-search').focus();$('#spirit-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',ev=>{if(ev.target.id==='layout-setting'){s.settings.layout=ev.target.value;applyLayout();save();}if(ev.target.id==='starter-base'){s.player.name=$('#sealer-name').value||'Sealer';starterBase=ev.target.value;starters();}if(ev.target.id==='spirit-filter'){filter=ev.target.value;render();}if(ev.target.id==='timing-setting'){s.settings.timing=ev.target.value;save();}if(ev.target.id==='import-file')importSave(ev.target.files[0]);if(ev.target.id==='ai-enabled'){s.settings.aiEnabled=ev.target.checked;save();if(ev.target.checked)checkAI();}if(ev.target.id==='ai-model'){s.settings.model=ev.target.value;save();}});
document.addEventListener('keydown',ev=>{const k=ev.key.toLowerCase();if(['INPUT','SELECT','TEXTAREA'].includes(ev.target.tagName)&&ev.target.type!=='range')return;if(k==='escape'){if(modal==='starter')return;closeModal();return;}if(modal){if(ritual&&(k===' '||k==='enter')){ev.preventDefault();sealPulse();}return;}if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))ev.preventDefault();keys.add(k);if(ev.repeat)return;if(k==='e'||k==='enter')interact();if(k==='b')bag();if(['1','2','3','4'].includes(k)&&!battle){view=['explore','spirits','atlas','journal'][Number(k)-1];render();}});
document.addEventListener('keyup',ev=>keys.delete(ev.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();persist();});window.addEventListener('pagehide',()=>persist());
async function boot(){try{db=await openDB();for(const sp of await dbAll('library'))library[sp.id]=sp;s=await dbGet('saves','main')||E.newGame();battle=s.battle||null;queue=s.generationQueue||[];s.inventory.ethers??=3;for(const i of s.spirits)i.pp??=E.stats(i,spOf(i)).pp;loaded=true;globalThis.spirimonSpecies=s.species;discoverRegion();render();if(!s.starter)starters();requestAnimationFrame(tick);setInterval(persist,15000);setInterval(processQueue,5000);}catch(err){$('#main').innerHTML='<div class="panel"><h1>Local storage is unavailable.</h1><p>Open Spirimon through Start-Spirimon.cmd in a regular browser window with site storage enabled.</p><p>'+esc(err.message)+'</p></div>';console.error(err);}}
boot();

function tempoHTML(ind,sp){const credits=battle.credits||{a:0,b:0},move=sp.moves[selectedMove],count=1+credits.a+borrow;let cost=0;for(let n=0;n<count;n++)cost+=E.actionCost(move,n);return'<div class="tempo-panel"><div class="commitment-label"><span>BORROW ACTIONS</span><span>Shared PP cost: '+cost+'</span></div><div class="style-selector">'+[0,1,2].map(n=>'<button class="'+(borrow===n?'selected':'')+'" data-action="borrow" data-value="'+n+'">'+(n===0?'Normal action':'Borrow +'+n)+'</button>').join('')+'</div><p class="tiny muted">'+(credits.a?'You have '+credits.a+' bonus action(s) owed this round. ':'')+(credits.b?'Opponent has '+credits.b+' bonus action(s) this round. ':'')+(borrow?'Repeat your selected move '+count+' times if PP allows. Opponent gains '+borrow+' extra action(s) next round.':'Later actions cost 1.5×, 2×, then more PP. Bonus actions never create further debt.')+'</p></div>';}
function useEther(){if(!(s.inventory.ethers>0))return toast('Buy soul draughts from Tavi.');const i=battle?s.spirits.find(x=>x.id===battle.ally):lead();if(!i)return;const max=E.stats(i,spOf(i)).pp;if(i.pp>=max)return toast('Your spirit’s PP pool is full.');s.inventory.ethers--;i.pp=Math.min(max,i.pp+Math.ceil(max*.6));closeModal();if(battle)enemyOnly('A soul draught restores your shared PP.');else{save();render();toast('Your spirit’s shared PP is restored.');}}

function applyLayout(){const mobile=s.settings.layout==='emulator'||s.settings.layout!=='desktop'&&(matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0);document.body.classList.toggle('emulator-mode',mobile);document.body.classList.toggle('exploring',view==='explore'&&!battle);document.body.classList.toggle('battling',!!battle);document.body.classList.toggle('portrait-allowed',!!s.settings.portraitAllowed);if(!$('#emulator-shell')){const shell=document.createElement('div');shell.id='emulator-shell';shell.innerHTML='<div class="emulator-controls"><div class="emu-pad"><span class="emu-pad-center"></span><button data-hold="up" aria-label="Move up">▲</button><button data-hold="left" aria-label="Move left">◀</button><button data-hold="right" aria-label="Move right">▶</button><button data-hold="down" aria-label="Move down">▼</button></div><div class="emu-ab">'+action('emu-b','B','','')+action('emu-a','A','','')+'</div><div class="emu-menu">'+action('settings','MENU','','')+action('bag','BAG','','')+action('fullscreen','⛶','','')+'</div></div>'+action('view','← Return to game','explore','mobile-return')+'<div class="portrait-prompt"><div class="rotate-icon">▱ ↻</div><h2>A world worth turning for.</h2><p>Rotate your phone sideways for the full Spirimon experience, with emulator-style controls.</p>'+action('fullscreen','Play in landscape','','btn primary')+'<div style="margin-top:12px">'+action('portrait-play','Continue in portrait','','btn ghost')+'</div></div>';document.body.appendChild(shell);}}
async function enterFullscreen(){try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();if(screen.orientation?.lock)await screen.orientation.lock('landscape');}catch{toast('Rotate your phone sideways to play in landscape.');}}
document.addEventListener('pointerdown',ev=>{const button=ev.target.closest('[data-hold]');if(!button)return;ev.preventDefault();const dir=button.dataset.hold,key={up:'w',left:'a',right:'d',down:'s'}[dir];button.setPointerCapture?.(ev.pointerId);button.classList.add('held');keys.add(key);});
function releaseTouch(ev){const button=ev.target.closest('[data-hold]');if(button){keys.delete({up:'w',left:'a',right:'d',down:'s'}[button.dataset.hold]);button.classList.remove('held');}}
document.addEventListener('pointerup',releaseTouch);document.addEventListener('pointercancel',()=>{keys.clear();document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));});window.addEventListener('resize',()=>{if(loaded)applyLayout();});
